/**
 * The curated text fonts (spec 6.2 #1; roadmap M4.3): free-licence only, every one under the
 * SIL Open Font License 1.1, with its licence text beside the file in public/fonts/ and its
 * copyright line recorded here. GENERATED by scripts/fonts-catalogue.py from the files on disk;
 * scripts/check-fonts.mjs fails the build if a font has no licence record, or a record no font.
 */

export type FontRecord = {
  id: string;
  name: string;
  file: string;
  licence: "OFL-1.1";
  copyright: string;
  source: string;
  /** How the text tool groups them. */
  kind: "serif" | "sans" | "display" | "script" | "mono";
};

